// === ESTRUCTURA DEL PATRÓN PROTOTYPE ===

// 1. Interfaz Prototype
interface Shape {
  clone(): Shape;
  getArea(): number;
  describe(): string;
}

// 2. Prototipo Concreto — Circle
class Circle implements Shape {
  constructor(
    public radius: number,
    public color: string,
    public position: { x: number; y: number }
  ) {}

  // Deep copy manual
  clone(): Circle {
    return new Circle(
      this.radius,
      this.color,
      { ...this.position } // copia el objeto anidado
    );
  }

  getArea() { return Math.PI * this.radius ** 2; }
  describe() {
    return `Circle(r=${this.radius}, ${this.color}, pos=${this.position.x},${this.position.y})`;
  }
}

// 3. Prototipo Concreto — Rectangle
class Rectangle implements Shape {
  constructor(
    public width: number,
    public height: number,
    public color: string,
    public position: { x: number; y: number }
  ) {}

  clone(): Rectangle {
    return new Rectangle(
      this.width,
      this.height,
      this.color,
      { ...this.position }
    );
  }

  getArea() { return this.width * this.height; }
  describe() {
    return `Rect(${this.width}x${this.height}, ${this.color})`;
  }
}

// 4. Uso — clonar sin acoplar a la clase
const original = new Circle(10, 'red', { x: 0, y: 0 });
const clone = original.clone();

clone.position.x = 100; // Modifico la copia
console.log(original.position.x); // 0 — el original no cambió
console.log(clone.position.x);    // 100 — la copia sí

