// Opción 3: Prototype pattern con clone()
interface Cloneable {
  clone(): this;
}

class Config implements Cloneable {
  constructor(
    public name: string,
    public settings: { theme: string; lang: string },
    public tags: string[]
  ) {}

  clone(): this {
    return structuredClone(this);
  }
}

const config = new Config('App', { theme: 'dark', lang: 'es' }, ['admin']);
const copy = config.clone();
copy.settings.theme = 'light';
// original.settings.theme sigue siendo 'dark'

